36		public Animal(Field field, Location location) {
37			super(field, location);
38			alive = true;
39			gender = gender.randomGender();
40			nocturnal = false;
41			sick = false;
42			sickProbability = 16;
43		}
44	
45	
46		abstract protected void normalAct(List<Animal> newAnimals);
47	
48	
49		public void act(List<Animal> newAnimals, TimeCycle time) {
50			incrementAge();
51			incrementHunger();
52			battleSickness();
53			if (isAlive()) {
54				if (time == TimeCycle.NIGHT && isNocturnal()) {
55	
56					normalAct(newAnimals);
57				} else if (time == TimeCycle.DAY && isNocturnal()) {
58	
59					normalAct(newAnimals);
60				} else if (time == TimeCycle.DAY && !isNocturnal()) {
61	
62					normalAct(newAnimals);
63				}
64			}
65		}
66	
67	
68		protected void incrementAge() {
69			age++;
70			if (age > getMaxAge()) {
71				setDead();
72			}
73		}
74	
75	
76		private boolean canBreed() {
77			Field field = getField();
78			List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
79			Iterator<Location> it = adjacent.iterator();
80			boolean returnValue = age >= getBreedingAge();
81			while (it.hasNext()) {
82				Location where = it.next();
83				Object animal = field.getAnimalAt(where);
84				if (animal instanceof Animal) {
85					Animal animalNear = (Animal) animal;
86	
87					if (animalNear.getClass().equals(this.getClass()) && getGender() != animalNear.getGender()) {
88						return returnValue;
89					}
90				}
91			}
92			return returnValue;
93		}
94	
95	
96		private int breed() {
97			int births = 0;
98			if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
99				births = rand.nextInt(getMaxLitterSize()) + 1;
100			}
101			return births;
102		}
103	
104	
105		protected void giveBirth(List<Animal> newAnimals) {
106	
107	
108			if (this.getGender() == Gender.FEMALE) {
109				Field field = getField();
110				List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
111				int births = breed();
112				for (int b = 0; b < births && free.size() > 0; b++) {
113					Location loc = free.remove(0);
114					Animal young = createNewAnimal(false, field, loc);
115					newAnimals.add(young);
116				}
117			}
118		}
