135	
136		protected void becomeSick() {
137			if (!isSick()) {
138				int randomNumber = rand.nextInt(getSickProbability());
139				if (randomNumber == 1) {
140					toggleSick();
141				}
142			}
143		}
144	
145	
146		protected void notSick() {
147			if (isSick()) {
148				int randomNumber = rand.nextInt(getRecoverProbability());
149				if (randomNumber == 1) {
150					toggleSick();
151					sickStep = 0;
152				}
153			}
154		}
155	
156	
157		protected void battleSickness() {
158			if (sick) {
159				if (sickStep >= maxSickStep) {
160					setDead();
161					return;
162				}
163				sickStep++;
164				Field field = getField();
165				if (field != null) {
166					List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
167					Iterator<Location> it = adjacent.iterator();
168					while (it.hasNext()) {
169						Location where = it.next();
170						Object animal = field.getAnimalAt(where);
171						if (animal instanceof Animal) {
172							Animal nearAnimal = (Animal) animal;
173							if (nearAnimal.getClass().equals(this.getClass())) {
174								nearAnimal.becomeSick();
175							}
176						}
177					}
178					this.notSick();
179				}
180			} else {
181				becomeSick();
182			}
183		}
184	
185	
186		protected void incrementHunger() {
187			foodLevel--;
188			if (foodLevel <= 0) {
189				setDead();
190			}
191		}
192	
193	
194		protected void toggleNocturnal() {
195			nocturnal = !nocturnal;
196	
197		}
198	
199	
