7	
8	
9		private static final Random rand = Randomizer.getRandom();
10	
11		private boolean cannibal;
12	
13		private int additionalFoodValue;
14	
15	
16		public Predator(boolean randomAge, Field field, Location location) {
17			super(field, location);
18			if (randomAge) {
19				setAge(rand.nextInt(getMaxAge()));
20				setFoodLevel(rand.nextInt(5));
21			} else {
22				setAge(0);
23				setFoodLevel(6);
24			}
25			cannibal = false;
26			additionalFoodValue = 0;
27			setMaxSickStep(30);
28		}
29	
30	
31		protected void normalAct(List<Animal> newAnimals) {
32			giveBirth(newAnimals);
33	
34			Location newLocation = findFood();
35			if (isAlive()) {
36				if (newLocation == null) {
37	
38					newLocation = getField().freeAnimalAdjacentLocation(getLocation());
39				}
40	
41				if (newLocation != null) {
42					setLocation(newLocation);
43				} else {
44	
45					setDead();
46				}
47			}
48		}
49	
50	
51		private Location findFood() {
52			Field field = getField();
53			List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
54			Iterator<Location> it = adjacent.iterator();
55			while (it.hasNext()) {
56				Location where = it.next();
57				Object animal = field.getAnimalAt(where);
58				if (animal instanceof Animal) {
59					Animal nearAnimal = (Animal) animal;
60	
61					if (nearAnimal.getFoodChainLevel() < this.getFoodChainLevel()) {
62	
63						if (nearAnimal.isAlive()) {
64							nearAnimal.setDead();
65							setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
66							return where;
67						}
68					}
69	
70	
71					if (nearAnimal.getFoodChainLevel() == this.getFoodChainLevel()) {
72						if (nearAnimal.isAlive() && this.isCannibal()) {
73							if (getFoodLevel() < 2 && nearAnimal.getClass().equals(this.getClass())) {
74								nearAnimal.setDead();
75								setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
76								return where;
77							}
78						}
79					}
80				}
81			}
82			return null;
83		}
84	
85	
86		public boolean isCannibal() {
87			return cannibal;
88		}
89	
90	
91		public void toggleCannibal() {
92			cannibal = !cannibal;
93		}
94	
95	
96		protected int getAdditionalFoodValue() {
97			return additionalFoodValue;
98		}
99	
100	
101		protected void setAdditionalFoodValue(int inputValue) {
102			additionalFoodValue = inputValue;
103		}
104	}
