3	
4	
5	public class Grass extends Plant {
6	
7		private static final Random rand = Randomizer.getRandom();
8	
9	
10		public Grass(Field field, Location location) {
11			super(field, location);
12	
13	
14			if (rand.nextDouble() <= 0.5) {
15				setMaxStage(3);
16			} else if (rand.nextDouble() <= 0.3) {
17				setMaxStage(2);
18			} else {
19				setMaxStage(1);
20			}
21			setStage(getMaxStage());
22		}
23	
24	
25		protected void increaseStage(Climate climate) {
26			super.increaseStage(climate);
27			if (climate.getCurrentSeason() == Season.SPRING && getStage() > 2) {
28				setStage(2);
29			} else if (climate.getCurrentSeason() == Season.SUMMER && getStage() > 3) {
30				setStage(3);
31			} else if (climate.getCurrentSeason() == Season.AUTUMN && getStage() > 2) {
32				setStage(2);
33			} else if (climate.getCurrentSeason() == Season.WINTER && getStage() > 1) {
34				setStage(1);
35			}
36		}
37	
38	
39		protected Color getObjectColor(Climate climate) {
40			switch (climate.getCurrentSeason()) {
41				case SPRING:
42					if (getStage() == 2) {
43						return new Color(34, 140, 61);
44					} else if (getStage() == 1) {
45						return new Color(68, 201, 104);
46					} else {
47						return new Color(131, 101, 57);
48					}
49				case SUMMER:
50					if (getStage() == 3) {
51						return new Color(11, 102, 35);
