6		private static final int SEASON_LENGTH = 16;
7	
8		private static final Random rand = Randomizer.getRandom();
9	
10		private Weather currentWeather;
11	
12		private Season currentSeason;
13	
14		private int humidity;
15	
16	
17		public Climate(Weather currentWeather) {
18			this.currentWeather = currentWeather;
19			currentSeason = Season.SPRING;
20		}
21	
22	
23		public void updateClimate(int step) {
24			updateSeason(step);
25	
26	
27			int humidityIncrease = rand.nextInt((20 - 10) + 1) + 10;
28	
29			if (humidity < 80 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
30				humidity += humidityIncrease;
31			} else if (humidity < 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD)) {
32				humidity += humidityIncrease;
33				currentWeather = Weather.CLOUD;
34			} else if (humidity > 100 && (currentWeather == Weather.SUN || currentWeather == Weather.CLOUD) && currentSeason != Season.WINTER) {
35				currentWeather = Weather.RAIN;
36			} else if (humidity > 80 && currentWeather == Weather.RAIN) {
37				humidity -= humidityIncrease;
38			} else {
39				humidity = 0;
40				currentWeather = Weather.SUN;
41			}
42		}
43	
44	
45		private void updateSeason(int step) {
46			switch ((step / SEASON_LENGTH) % 4) {
47				case 0:
48					currentSeason = Season.SPRING;
49					break;
50				case 1:
51					currentSeason = Season.SUMMER;
52					break;
53				case 2:
54					currentSeason = Season.AUTUMN;
55					break;
56				case 3:
57					currentSeason = Season.WINTER;
58					break;
59			}
60		}
