4	public class FieldStats {
5	
6		private HashMap<Class, Counter> counters;
7	
8		private boolean countsValid;
9	
10	
11		public FieldStats() {
12	
13	
14			counters = new HashMap<>();
15			countsValid = true;
16		}
17	
18	
19		public String getPopulationDetails(Field field) {
20			StringBuffer buffer = new StringBuffer();
21			if (!countsValid) {
22				generateCounts(field);
23			}
24			for (Class key : counters.keySet()) {
25				Counter info = counters.get(key);
26				buffer.append(info.getName());
27				buffer.append(": ");
28				buffer.append(info.getCount());
29				buffer.append(' ');
30			}
31			return buffer.toString();
32		}
33	
34	
35		public void reset() {
36			countsValid = false;
37			for (Class key : counters.keySet()) {
38				Counter count = counters.get(key);
39				count.reset();
40			}
41		}
42	
43	
44		public void incrementCount(Class animalClass) {
45			Counter count = counters.get(animalClass);
46			if (count == null) {
47	
48	
49				count = new Counter(animalClass.getName());
50				counters.put(animalClass, count);
51			}
52			count.increment();
53		}
54	
55	
56		public void countFinished() {
57			countsValid = true;
58		}
59	
60	
61		public boolean isViable(Field field) {
62	
63			int nonZero = 0;
64			if (!countsValid) {
65				generateCounts(field);
66			}
67			for (Class key : counters.keySet()) {
68				Counter info = counters.get(key);
69				if (info.getCount() > 0) {
70					nonZero++;
71				}
72			}
73			return nonZero > 1;
74		}
75	
76	
77		private void generateCounts(Field field) {
78			reset();
79			for (int row = 0; row < field.getDepth(); row++) {
80				for (int col = 0; col < field.getWidth(); col++) {
81					Object animal = field.getAnimalAt(row, col);
82					if (animal != null) {
83						incrementCount(animal.getClass());
84					}
85				}
86			}
87			countsValid = true;
88		}
89	
90	
91		public int getPopulationCount(Field field, Class key) {
92			if (!countsValid) {
93				generateCounts(field);
94			}
95			int total = 0;
96			for (Class currentKey : counters.keySet()) {
97				if (currentKey.equals(key)) {
98					Counter counter = counters.get(currentKey);
99					total = total + counter.getCount();
100				}
101			}
102			return total;
103		}
104	}
