46	
47		private Climate climate;
48	
49		private int sickPercentage;
50	
51	
52		public Simulator() {
53			this(DEFAULT_DEPTH, DEFAULT_WIDTH);
54			currentTimeCycle = DEFAULT_TIMECYCLE;
55		}
56	
57	
58		public Simulator(int depth, int width) {
59			if (width <= 0 || depth <= 0) {
60				System.out.println("The dimensions must be greater than zero.");
61				System.out.println("Using default values.");
62				depth = DEFAULT_DEPTH;
63				width = DEFAULT_WIDTH;
64			}
65	
66	
67			animals = new ArrayList<>();
