88	
89		public void simulate(int numSteps) {
90			for (int step = 1; step <= numSteps && gridView.isViable(field); step++) {
91				simulateOneStep();
92				delay(60);
93			}
94		}
95	
96	
97		public void simulateOneStep() {
98			step++;
99			climate.updateClimate(step);
100	
101	
102			for (Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
103				Plant plant = it.next();
104				plant.increaseStage(climate);
105			}
106	
107	
108			List<Animal> newAnimals = new ArrayList<>();
109	
110			for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
111				Animal animal = it.next();
112				animal.act(newAnimals, currentTimeCycle);
113				if (!animal.isAlive()) {
114					it.remove();
115				}
116			}
117	
118	
119			animals.addAll(newAnimals);
120	
121	
122			if (step % TIMECYCLE_LENGTH == 0) {
123				currentTimeCycle = currentTimeCycle.toggleTimeCycle(currentTimeCycle);
124			}
125	
126	
127			int count = 0;
128			for (Animal i : animals) {
129				if (i.isSick()) {
130					count++;
131				}
132			}
133	
134			sickPercentage = (count * 100) / animals.size();
135			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
136			graphView.showStatus(step, field);
137		}
