156			field.clear();
157	
158			for (int row = 0; row < field.getDepth(); row++) {
159				for (int col = 0; col < field.getWidth(); col++) {
160					Location location = new Location(row, col);
161	
162	
163					if (rand.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
164						Flower flower = new Flower(field, location);
165						plants.add(flower);
166					} else {
167						Grass grass = new Grass(field, location);
168						plants.add(grass);
169					}
170	
171	
172					if (rand.nextDouble() <= BIRD_CREATION_PROBABILITY) {
