179						graphView.setColor(Mouse.class, mouse.getObjectColor(climate));
180					} else if (rand.nextDouble() <= DUCK_CREATION_PROBABILITY) {
181						Duck duck = new Duck(true, field, location);
182						animals.add(duck);
183						graphView.setColor(Duck.class, duck.getObjectColor(climate));
184					} else if (rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
185						Wolf wolf = new Wolf(true, field, location);
186						animals.add(wolf);
187						graphView.setColor(Wolf.class, wolf.getObjectColor(climate));
188					} else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
189						Bear bear = new Bear(true, field, location);
190						animals.add(bear);
191						graphView.setColor(Bear.class, bear.getObjectColor(climate));
192					}
193	
194				}
195			}
196		}
