85		class GraphPanel extends JComponent {
86			private static final double SCALE_FACTOR = 0.8;
87	
88	
89			private BufferedImage graphImage;
90			private int[] lastVal;
91			private int yMax;
92	
93	
94			public GraphPanel(int width, int height, int startMax) {
95				graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
96				clearImage();
97				lastVal = new int[classes.size()];
98				Arrays.fill(lastVal, height);
99				yMax = startMax;
100			}
101	
102	
103			public void newRun() {
104				int height = graphImage.getHeight();
105				int width = graphImage.getWidth();
106	
107				Graphics g = graphImage.getGraphics();
108				g.copyArea(4, 0, width - 4, height, -4, 0);
109				g.setColor(Color.BLACK);
110				g.drawLine(width - 4, 0, width - 4, height);
111				g.drawLine(width - 2, 0, width - 2, height);
112				lastVal = new int[classes.size()];
113				Arrays.fill(lastVal, height);
114				repaint();
115			}
116	
117	
118			public void update(int step, Field field, FieldStats stats) {
119	
120				Graphics g = graphImage.getGraphics();
121	
122				int height = graphImage.getHeight();
123				int width = graphImage.getWidth();
124	
125	
126				g.copyArea(1, 0, width - 1, height, -1, 0);
127	
128				stats.reset();
129	
130				int i = 0;
131				for (Iterator<Class<?>> it = classes.iterator(); it.hasNext(); i++) {
132					Class<?> nextClass = it.next();
133					int count = stats.getPopulationCount(field, nextClass);
134	
135	
136					int y = height - ((height * count) / yMax) - 1;
137					while (y < 0) {
138						scaleDown();
139						y = height - ((height * count) / yMax) - 1;
140					}
141					g.setColor(LIGHT_GRAY);
142					g.drawLine(width - 2, y, width - 2, height);
143					g.setColor(colors.get(nextClass));
144					g.drawLine(width - 3, lastVal[i], width - 2, y);
145					lastVal[i] = y;
146				}
147	
148				repaint();
149	
150				stepLabel.setText("" + step);
151				countLabel.setText(stats.getPopulationDetails(field));
152	
153			}
154	
155	
156			public void scaleDown() {
157				Graphics g = graphImage.getGraphics();
158				int height = graphImage.getHeight();
159				int width = graphImage.getWidth();
160	
161				BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
162						BufferedImage.TYPE_INT_RGB);
163				Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();
164	
165				gtmp.scale(1.0, SCALE_FACTOR);
166				gtmp.drawImage(graphImage, 0, 0, null);
167	
168				int oldTop = (int) (height * (1.0 - SCALE_FACTOR));
169	
170				g.setColor(Color.WHITE);
171				g.fillRect(0, 0, width, oldTop);
172				g.drawImage(tmpImage, 0, oldTop, null);
173	
174				yMax = (int) (yMax / SCALE_FACTOR);
175	
176				for (int i = 0; i < lastVal.length; i++) {
177					lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
178				}
179	
180				repaint();
181			}
182	
183	
184			final public void clearImage() {
185				Graphics g = graphImage.getGraphics();
186				g.setColor(Color.WHITE);
187				g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
188				repaint();
189			}
190	
191	
192			public Dimension getPreferredSize() {
193				return new Dimension(graphImage.getWidth(), graphImage.getHeight());
194			}
195	
196	
197			public boolean isOpaque() {
198				return true;
199			}
200	
201	
202			public void paintComponent(Graphics g) {
203				if (graphImage != null) {
204					g.drawImage(graphImage, 0, 0, null);
205				}
206			}
207		}
208	}
