	Random rand = Randomizer.getRandom();
	field.clear();

	double mouseThreshold = BIRD_CREATION_PROBABILITY + MOUSE_CREATION_PROBABILITY;
	double duckThreshold = mouseThreshold + DUCK_CREATION_PROBABILITY;
